package com.lbos.commercecustomer.entity; import jakarta.persistence.*;import java.util.*;import java.time.*;import java.math.*; @Entity @Table(name="customer_review",uniqueConstraints= @UniqueConstraint(name="uq_review_order_product",columnNames={"order_id","product_id"})) public class CustomerReview {@Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="customer_review_id") private UUID id; @Column(name="order_id",nullable=false) private Long orderId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id") private Product product; @Column(name="customer_id",nullable=false) private UUID customerId; @Column(nullable=false) private short rating; @Column(name="review_text",columnDefinition="TEXT") private String text; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @PrePersist void add(){createdAt=OffsetDateTime.now();} public CustomerReview(){} public UUID getId(){return id;} public void setId(UUID v){id=v;} public Long getOrderId(){return orderId;} public void setOrderId(Long v){orderId=v;} public Product getProduct(){return product;} public void setProduct(Product v){product=v;} public UUID getCustomerId(){return customerId;} public void setCustomerId(UUID v){customerId=v;} public short getRating(){return rating;} public void setRating(short v){rating=v;} public String getText(){return text;} public void setText(String v){text=v;} public OffsetDateTime getCreatedAt(){return createdAt;}}